// src/tools/setup.ts
function registerSetupTool(server, store2, config2) {
  server.registerTool(
    "menese_setup",
    {
      description: "Create or import a Menese wallet. Actions: 'new' generates a fresh wallet, 'import' restores from an existing hex seed, 'status' shows current wallet info.",
      inputSchema: {
        action: external_exports.enum(["new", "import", "status"]).describe("Action to perform"),
        seed: external_exports.string().length(64).optional().describe("64-char hex seed (for 'import' action only)")
      }
    },
    async ({ action, seed: importSeed }) => {
      if (action === "status") {
        const current = store2.get();
        if (!current) {
          return { content: [{ type: "text", text: "No wallet configured. Use action 'new' to create one or 'import' to restore." }] };
        }
        const addrRes2 = await getAllAddresses(config2, current.principal, current.seed);
        const evm2 = addrRes2.ok ? addrRes2.data.evm?.evmAddress ?? "\u2014" : "\u2014";
        const sol2 = addrRes2.ok ? addrRes2.data.solana?.address ?? "\u2014" : "\u2014";
        const btc2 = addrRes2.ok ? addrRes2.data.bitcoin?.bech32Address ?? "\u2014" : "\u2014";
        return {
          content: [{
            type: "text",
            text: JSON.stringify({
              principal: current.principal,
              eth: evm2,
              sol: sol2,
              btc: btc2,
              agentCanisterId: current.agentCanisterId ?? null
            }, null, 2)
          }]
        };
      }
      let seed;
      if (action === "import") {
        if (!importSeed || !/^[0-9a-fA-F]{64}$/.test(importSeed)) {
          return {
            content: [{ type: "text", text: "Invalid seed. Expected 64 hex characters (32 bytes)." }],
            isError: true
          };
        }
        seed = importSeed.toLowerCase();
      } else {
        seed = generateSeed();
      }
      const principal = getPrincipalFromSeed(seed);
      store2.set({ seed, principal });
      const addrRes = await getAllAddresses(config2, principal, seed);
      const evm = addrRes.ok ? addrRes.data.evm?.evmAddress ?? "\u2014" : "\u2014";
      const sol = addrRes.ok ? addrRes.data.solana?.address ?? "\u2014" : "\u2014";
      const btc = addrRes.ok ? addrRes.data.bitcoin?.bech32Address ?? "\u2014" : "\u2014";
      return {
        content: [{
          type: "text",
          text: JSON.stringify({
            status: action === "import" ? "Wallet imported" : "Wallet created",
            principal,
            eth: evm,
            sol,
            btc,
            seed: action === "new" ? seed : void 0
          }, null, 2)
        }]
      };
    }
  );
}

