var RULE_TYPE_MAP = {
  dca: { DCA: null },
  take_profit: { TakeProfit: null },
  stop_loss: { StopLoss: null }
};
function registerStrategyTool(server, store2, config2) {
  server.registerTool(
    "menese_strategy",
    {
      description: "Manage automated trading strategies: DCA (dollar-cost averaging), Take Profit (sell above target), Stop Loss (sell below threshold).",
      inputSchema: {
        action: external_exports.enum(["create", "list", "cancel"]).describe("Action to perform"),
        strategyType: external_exports.enum(["dca", "take_profit", "stop_loss"]).optional().describe("Strategy type (required for create)"),
        chain: external_exports.enum(SUPPORTED_CHAINS).optional().describe("Target chain (required for create)"),
        amount: external_exports.string().optional().describe("Amount per execution (decimal, for create)"),
        intervalSeconds: external_exports.number().min(60).optional().describe("Interval between DCA executions in seconds (min 60)"),
        maxExecutions: external_exports.number().min(1).optional().describe("Max number of executions"),
        targetPrice: external_exports.string().optional().describe("Target price in USD (for take_profit/stop_loss)"),
        ruleId: external_exports.number().optional().describe("Rule ID (for cancel)")
      }
    },
    async ({ action, strategyType, chain: chain2, amount, intervalSeconds, maxExecutions, targetPrice, ruleId }) => {
      const identity = store2.get();
      if (!identity) {
        return { content: [{ type: "text", text: "No wallet configured. Use menese_setup first." }], isError: true };
      }
      if (action === "list") {
        const result2 = await listStrategies(config2, identity.seed);
        return {
          content: [{
            type: "text",
            text: JSON.stringify(result2, bigIntReplacer, 2)
          }]
        };
      }
      if (action === "cancel") {
        if (ruleId == null) {
          return { content: [{ type: "text", text: "ruleId is required for cancel." }], isError: true };
        }
        const result2 = await deleteStrategy(config2, identity.seed, ruleId);
        return {
          content: [{
            type: "text",
            text: JSON.stringify(result2, bigIntReplacer, 2)
          }]
        };
      }
      if (!strategyType || !chain2 || !amount) {
        return {
          content: [{ type: "text", text: "strategyType, chain, and amount are required for create." }],
          isError: true
        };
      }
      const chainType = CHAIN_TYPE_MAP[chain2];
      const ruleType = RULE_TYPE_MAP[strategyType];
      if (!chainType || !ruleType) {
        return { content: [{ type: "text", text: "Invalid chain or strategy type." }], isError: true };
      }
      const decimals = CHAIN_DECIMALS[chain2] ?? 18;
      const triggerPrice = targetPrice ? BigInt(Math.round(parseFloat(targetPrice) * 1e6)) : 0n;
      const rule = {
        chainType,
        ruleType,
        triggerPrice,
        sizePct: 100n,
        positionId: 0n,
        id: 0n,
        status: { Draft: null },
        createdAt: BigInt(Date.now()) * 1000000n,
        apyMigrationConfig: [],
        lpConfig: [],
        scheduledConfig: [],
        volatilityConfig: [],
        swapAmountDrops: [],
        swapAmountLamports: [],
        swapAmountWei: [],
        dcaConfig: []
      };
      if (chain2 === "solana") {
        rule.swapAmountLamports = [parseAmount(amount, 9)];
      } else if (chain2 === "xrp") {
        rule.swapAmountDrops = [parseAmount(amount, 6)];
      } else {
        rule.swapAmountWei = [parseAmount(amount, decimals)];
      }
      if (strategyType === "dca" && intervalSeconds) {
        rule.dcaConfig = [{ intervalSeconds: BigInt(intervalSeconds), maxExecutions: maxExecutions ? [BigInt(maxExecutions)] : [] }];
      }
      const result = await addStrategy(config2, identity.seed, rule);
      return {
        content: [{
          type: "text",
          text: JSON.stringify(result, bigIntReplacer, 2)
        }]
      };
    }
  );
}
function parseAmount(value, decimals) {
  const parts = value.split(".");
  const whole = parts[0] ?? "0";
  let frac = parts[1] ?? "";
  if (frac.length > decimals) frac = frac.slice(0, decimals);
  frac = frac.padEnd(decimals, "0");
  return BigInt(whole) * 10n ** BigInt(decimals) + BigInt(frac);
}

