function hexToBytes3(hex) {
  const clean2 = hex.startsWith("0x") ? hex.slice(2) : hex;
  const bytes = new Uint8Array(clean2.length / 2);
  for (let i = 0; i < bytes.length; i++) {
    bytes[i] = parseInt(clean2.substring(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}
